create table medical_devices(id uuid primary key, external_id varchar(120) not null unique, device_type varchar(120) not null, manufacturer varchar(120), model varchar(120), status varchar(30) not null, registered_at timestamptz not null); create table telemetry_sessions(id uuid primary key, patient_id uuid not null, visit_id uuid, pre_hospital_encounter_id uuid, source_context varchar(60) not null, started_at timestamptz not null, ended_at timestamptz); create table biometric_observations(id uuid primary key, session_id uuid not null, device_id uuid not null, type varchar(120) not null, value double precision not null, unit varchar(40), measured_at timestamptz not null, source_context varchar(60) not null); create index idx_obs_session_time on biometric_observations(session_id,measured_at);
create table outbox_events(id uuid primary key, topic varchar(160) not null, event_key varchar(160) not null, payload varchar(8000) not null, created_at timestamptz not null, published_at timestamptz); create index idx_outbox_pending on outbox_events(published_at,created_at);
